// Exact selected Main; dependency doubles are checked against native control-flow event plans.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct Event { int kind,a,b; float x,y,z; };
static int errors,scenarios,cursor,ending,checks,strings,handles,current_name,missing_target;
static int* contest_state;
static const Event* events;
static int event_count;
static const char* names[]={"M_AC_DummyTargetCentre","M_AC_DummyTargetRight","M_AC_DummyTargetLeft","M_AC_DummyTargetFront","unknown",""};
static void check(bool v) { if(!v) { if(errors<8)fprintf(stderr,"scenario %d event %d termination %d\n",scenarios,cursor,ending); ++errors; } }
static const Event& next(int kind) {
    if(cursor>=event_count) {fprintf(stderr,"event plan exhausted\n");exit(1);}
    const Event& e=events[cursor++];check(e.kind==kind);return e;
}
class CCharString {
public:
    const char* text;
    CCharString(const char* p,long n=-1):text(p){check(n==-1);++strings;}
    CCharString(const CCharString& p):text(p.text){++strings;}
    ~CCharString(){--strings;}
    bool operator==(const char* p)const{return !strcmp(text,p);}
};
class C3DVector {
public:
    float X,Y,Z;
    C3DVector(float x,float y,float z):X(x),Y(y),Z(z){}
    C3DVector(const C3DVector& v):X(v.X),Y(v.Y),Z(v.Z){}
    const C3DVector operator+(const C3DVector& v)const{return C3DVector(X+v.X,Y+v.Y,Z+v.Z);}
};
class CScriptThing {
public:
    int id;
    CScriptThing(int n=0):id(n){++handles;}
    CScriptThing(const CScriptThing& t):id(t.id){++handles;}
    ~CScriptThing(){--handles;}
    CCharString GetDataString()const{next(1);check(id==0);return CCharString(names[current_name]);}
    const C3DVector& GetPos()const {
        const Event& e=next(3);check(e.a==id);
        static const C3DVector first(8.0f,16.0f,4.0f),last(40.0f,48.0f,20.0f),zero(0.0f,0.0f,0.0f);
        return id==0?first:missing_target?zero:last;
    }
    bool MsgIsHitByWithProjectileWeapon(const CCharString& name,float& power)const {
        const Event& e=next(8);check(id==0&&!strcmp(name.text,"SCRIPT_NAME_HERO"));power=e.x;return e.a!=0;
    }
};
class CGameScriptInterfaceBase {
public:
    CScriptThing hero;
    CGameScriptInterfaceBase():hero(3){}
    CScriptThing GetThingWithScriptName(const CCharString& name)const {
        const Event& e=next(2);check(!strcmp(name.text,e.a==1?names[current_name]:"AC_PlayerRing"));return CScriptThing(e.a);
    }
    void NewScriptFrame(){const Event& e=next(5);*contest_state=e.b;}
    void EntityTeleportToPosition(const CScriptThing& t,const C3DVector& v,float angle,bool one,bool two) {
        const Event& e=next(6);check(t.id==0&&v.X==e.x&&v.Y==e.y&&v.Z==e.z&&angle==0.0f&&!one&&!two);
    }
    void EntitySetFacingAngleTowardsThing(const CScriptThing& t,const CScriptThing& other,bool immediate){next(7);check(t.id==0&&other.id==2&&!immediate);}
    CScriptThing& GetHero(){next(9);return hero;}
    void PlaySoundOnThing(const CScriptThing& t,const CCharString& name){next(10);check(t.id==3&&!strcmp(name.text,"SND_ARROWIMPACT_02"));}
    void EntityPlayObjectAnimation(const CScriptThing& t,const CCharString& name,bool loop){next(12);check(t.id==0&&!strcmp(name.text,"GET_HIT")&&!loop);}
};
class CScriptDef {
public:
    long ArcheryScoreDummyCentre,ArcheryScoreDummyRight,ArcheryScoreDummyLeft,ArcheryScoreDummyFront;
    long ArcheryDummySpeedFast,ArcheryDummySpeedMedium,ArcheryDummySpeedSlow;
};
template<class T> class CDefPointer {public:T* Data;T* operator->()const{return Data;}};
CDefPointer<const CScriptDef> pGlobalScriptDef;
namespace NScript {
class CV_ArcheryCompetitionScript {
public:
    enum {CONTEST_WAITING=0,CONTEST_COUNTDOWN=1,CONTEST_FINISHED=2,CONTEST_STARTED=3};
    int ContestState;
    void CalculateScoreForHit(long points,float power){const Event& e=next(11);check(points==e.a&&power==e.x);}
    class CAC_DummyMoving {
    public:
        CGameScriptInterfaceBase& Game;CScriptThing Me;CV_ArcheryCompetitionScript& ParentClass;
        long PointsValue,Steps;
        CAC_DummyMoving(CGameScriptInterfaceBase& g,CV_ArcheryCompetitionScript& p):Game(g),Me(0),ParentClass(p),PointsValue(99),Steps(8){}
        bool IsActiveThreadTerminating(){next(4);return ++checks==ending;}
        void Main();
    };
};
}

void NScript::CV_ArcheryCompetitionScript::CAC_DummyMoving::Main()
{
    CCharString targetThingName=Me.GetDataString();
    CScriptThing targetThing=Game.GetThingWithScriptName(targetThingName);
    C3DVector startPos=Me.GetPos();
    C3DVector targetPos=targetThing.GetPos();
    CCharString dummyScriptName=Me.GetDataString();
    if (dummyScriptName=="M_AC_DummyTargetCentre") {
        if (IsActiveThreadTerminating()) return;
        PointsValue=pGlobalScriptDef->ArcheryScoreDummyCentre;
        Steps=pGlobalScriptDef->ArcheryDummySpeedFast;
    } else if (dummyScriptName=="M_AC_DummyTargetRight") {
        if (IsActiveThreadTerminating()) return;
        PointsValue=pGlobalScriptDef->ArcheryScoreDummyRight;
        Steps=pGlobalScriptDef->ArcheryDummySpeedMedium;
    } else if (dummyScriptName=="M_AC_DummyTargetLeft") {
        if (IsActiveThreadTerminating()) return;
        PointsValue=pGlobalScriptDef->ArcheryScoreDummyLeft;
        Steps=pGlobalScriptDef->ArcheryDummySpeedSlow;
    } else if (dummyScriptName=="M_AC_DummyTargetFront") {
        if (IsActiveThreadTerminating()) return;
        PointsValue=pGlobalScriptDef->ArcheryScoreDummyFront;
        Steps=pGlobalScriptDef->ArcheryDummySpeedMedium;
    } else {
        if (IsActiveThreadTerminating()) return;
    }
    bool reverse=false;
    C3DVector vector((targetPos.X-startPos.X)/Steps,(targetPos.Y-startPos.Y)/Steps,0.0f);
    C3DVector reversevector((startPos.X-targetPos.X)/Steps,(startPos.Y-targetPos.Y)/Steps,0.0f);
    Game.NewScriptFrame();
    if (IsActiveThreadTerminating()) return;
    Game.NewScriptFrame();
    if (IsActiveThreadTerminating()) return;
    long count=0;
    float hitPower=0.0f;
    for (;!false;Game.NewScriptFrame()) {
        if (IsActiveThreadTerminating()) return;
        while (ParentClass.ContestState!=CONTEST_STARTED) {
            Game.NewScriptFrame();
            if (IsActiveThreadTerminating()) return;
        }
        if (IsActiveThreadTerminating()) return;
        while (ParentClass.ContestState!=CONTEST_FINISHED && ParentClass.ContestState!=CONTEST_WAITING) {
            Game.NewScriptFrame();
            if (IsActiveThreadTerminating()) return;
            if (reverse) {
                if (IsActiveThreadTerminating()) return;
                Game.EntityTeleportToPosition(Me,targetPos+C3DVector(reversevector.X*(float)count,reversevector.Y*(float)count,0.0f),0.0f,false,false);
            } else {
                if (IsActiveThreadTerminating()) return;
                Game.EntityTeleportToPosition(Me,startPos+C3DVector(vector.X*(float)count,vector.Y*(float)count,0.0f),0.0f,false,false);
            }
            Game.EntitySetFacingAngleTowardsThing(Me,Game.GetThingWithScriptName("AC_PlayerRing"),false);
            if (Me.MsgIsHitByWithProjectileWeapon("SCRIPT_NAME_HERO",hitPower)) {
                if (IsActiveThreadTerminating()) return;
                Game.PlaySoundOnThing(Game.GetHero(),"SND_ARROWIMPACT_02");
                ParentClass.CalculateScoreForHit(PointsValue,hitPower);
                Game.EntityPlayObjectAnimation(Me,"GET_HIT",false);
            }
            ++count;
            if (count==Steps) {
                if (IsActiveThreadTerminating()) return;
                reverse=!reverse;
                count=0;
            }
        }
        if (IsActiveThreadTerminating()) return;
    }
}

