int main() {
    for(unsigned i=0;i<sizeof(plans)/sizeof(plans[0]);++i) {
        const Plan& p=plans[i];
        for(int stop=1;stop<=p.terms;++stop) {
            ++scenarios;events=p.events;event_count=p.count;cursor=checks=0;ending=stop;current_name=p.name;missing_target=p.missing;
            CScriptDef def;memset(&def,0,sizeof(def));def.ArcheryScoreDummyCentre=20;def.ArcheryScoreDummyRight=40;def.ArcheryScoreDummyLeft=30;def.ArcheryScoreDummyFront=10;
            def.ArcheryDummySpeedFast=1<<p.speed;def.ArcheryDummySpeedMedium=2<<p.speed;def.ArcheryDummySpeedSlow=4<<p.speed;pGlobalScriptDef.Data=&def;
            {
                CGameScriptInterfaceBase game;NScript::CV_ArcheryCompetitionScript parent;parent.ContestState=0;contest_state=&parent.ContestState;
                NScript::CV_ArcheryCompetitionScript::CAC_DummyMoving row(game,parent);row.Main();
                check(checks==stop&&cursor>0&&events[cursor-1].kind==4);
                check(strings==0&&handles==2);
                check(row.PointsValue==(stop==1?99:p.points)&&row.Steps==(stop==1?8:p.steps));
            }
            check(strings==0&&handles==0);
        }
    }
    if(errors){fprintf(stderr,"%d errors in %d scenarios\n",errors,scenarios);return 1;}
    puts("00e36d50_TEST PASS");return 0;
}